package http

import "net/http"

// This HTML is only registered behind ownerOnly, never through the public
// FileServer. It uses textContent for all response-driven UI text.
const ownerSolanaValidatorPageHTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<meta name=\"robots\" content=\"noindex,nofollow\"><title>Koschei | Solana Validator Observations</title>\n<style>\n:root{color-scheme:dark;font:15px/1.5 system-ui,sans-serif;background:#081119;color:#e3f5f2}\n*{box-sizing:border-box}body{margin:0}main{max-width:1050px;margin:auto;padding:24px 16px}\na{color:#78e7da}h1{font-size:clamp(26px,5vw,38px)}\nsection{padding:20px;border:1px solid #244550;border-radius:14px;background:#0d202b;margin:16px 0}\nbutton{font:inherit;padding:12px;border:1px solid #46847b;background:#15433b;color:#e9fff8;border-radius:8px}\nbutton:disabled{opacity:.55}table{border-collapse:collapse;width:100%;min-width:780px}\nth,td{padding:9px;text-align:left;border-bottom:1px solid #2a4449;font-size:13px;overflow-wrap:anywhere}\n.scroll{overflow:auto}.muted{color:#adbfbd}.boundary{border-left:3px solid #dec071;padding:12px;background:#2a2820}\n</style></head><body><main>\n<nav><a href=\"/owner-production\">Owner console</a> · <a href=\"/owner/soc\">SOC</a></nav>\n<h1>Solana validator observations</h1>\n<p class=\"muted\">Operator-only, opt-in, read-only RPC collection. This page makes no RPC request until you select the button.</p>\n<div class=\"boundary\">OBSERVED ≠ VERIFIED · Validator statistics are not a decentralization score, risk rating or proof of chain safety. No data is persisted or promoted into ARVIS customer verdicts. A bounded sample is shown, not the complete validator list.</div>\n<section><button type=\"button\" id=\"collect\">Collect bounded validator evidence</button>\n<p id=\"status\" role=\"status\" aria-live=\"polite\">No probe requested. Availability unknown.</p><div id=\"summary\"></div></section>\n<section class=\"scroll\"><h2>Observed sample</h2><table><thead><tr><th>Vote account</th><th>Node</th><th>Delinquent</th><th>Stake share</th><th>Evidence ID</th></tr></thead><tbody id=\"rows\"></tbody></table></section>\n</main><script>\n(function(){\n\"use strict\";\nvar button=document.getElementById(\"collect\"),status=document.getElementById(\"status\"),summary=document.getElementById(\"summary\"),rows=document.getElementById(\"rows\");\nfunction cell(row,value){var c=document.createElement(\"td\");c.textContent=String(value);row.appendChild(c);}\nfunction line(value){var p=document.createElement(\"p\");p.textContent=value;summary.appendChild(p);}\nbutton.addEventListener(\"click\",async function(){\nbutton.disabled=true;status.textContent=\"Reading governed RPC (up to 12 seconds)…\";\nrows.replaceChildren();summary.replaceChildren();\ntry{\n  var response=await fetch(\"/api/owner/radar/solana/validators\",{method:\"GET\",credentials:\"same-origin\",cache:\"no-store\",headers:{\"Accept\":\"application/json\"}});\n  var payload=await response.json();\n  if(!response.ok||payload.ok!==true||!payload.telemetry){throw Error(\"Unavailable (\"+String(payload.code||response.status)+\"). No safety conclusion.\");}\n  var data=payload.telemetry;\n  status.textContent=\"Observation captured at \"+String(data.observed_at||\"unknown\")+\" · \"+(data.from_cache?\"cached RPC observation\":\"new RPC observation\");\n  line(\"Source: \"+String(data.source||\"unknown\")+\" · Network: \"+String(data.network||\"unknown\")+\" · Status: \"+String(data.evidence_status||\"unknown\"));\n  line(\"Current: \"+String(data.current_count)+\" · Delinquent: \"+String(data.delinquent_count)+\" · Sampled: \"+String(data.sampled)+\" · Truncated: \"+String(data.truncated));\n  line(\"RPC attempts this process: \"+String(data.probe_attempts)+\" · Failures: \"+String(data.probe_failures)+\" · Persisted: NO · Security verdict: NOT EVALUATED\");\n  (Array.isArray(data.observations)?data.observations:[]).forEach(function(item){\n    var row=document.createElement(\"tr\");\n    cell(row,item.vote_pubkey||\"unknown\");cell(row,item.node_pubkey||\"unknown\");cell(row,item.delinquent===true?\"YES\":\"NO\");\n    cell(row,typeof item.stake_share_pct===\"number\"?item.stake_share_pct.toFixed(3)+\"%\":\"UNKNOWN\");\n    cell(row,item.evidence_id||\"unknown\");rows.appendChild(row);\n  });\n}catch(err){status.textContent=String(err&&err.message||\"Probe unavailable\")+\" · Evidence remains UNKNOWN.\";}\nfinally{button.disabled=false;}\n});\n})();\n</script></body></html>"

func ownerSolanaValidatorPage(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = w.Write([]byte(ownerSolanaValidatorPageHTML))
}
